import wrapt
import socket


class RetryWhenSocketError(object):
    """Decorator to retry decorated method in case of exception."""

    def __init__(self, num):
        """
        :param integer num: Number of possible retries.
        """
        self._num = num
        self._called = 0

    @wrapt.decorator
    def __call__(self, wrapped, instance, args, kwargs):
        while self._called < self._num:
            try:
                return wrapped(*args, **kwargs)
            except socket.error:
                self._called += 1
        raise socket.error
